-- v0.35: player testing administration. Apply after schema.sql, chat roles v2,
-- the chapter-II chat catalog and covens. Repeatable; keeps players and all history.
begin;
create schema if not exists game_admin;
revoke all on schema game_admin from public, anon, authenticated;

alter table public.player_progress add column if not exists support_revision bigint not null default 0;
alter table public.player_wallet add column if not exists admin_revision bigint not null default 0;

create table if not exists game_admin.settings (key text primary key, value jsonb not null);
insert into game_admin.settings values ('installedAt', to_jsonb(clock_timestamp())) on conflict do nothing;
-- ADMIN_RULES BEGIN
-- generated by tools/build-admin-config.mjs
insert into game_admin.settings(key,value) values ('rules', $rules${"catalog":{"coins":{"name":"Монеты","icon":"icon_coin","type":"money","storage":"wallet"},"lunar_shard":{"name":"Лунный осколок","icon":"icon_shard","type":"item","storage":"bag"},"lunar_flame":{"name":"Лунный огонёк","icon":"lunar_flame_01","type":"story","storage":"story"},"moon_herb":{"name":"Лунная трава","icon":"icon_moon_herb","type":"item","storage":"bag"},"crimson_ember":{"name":"Багровый уголь","icon":"icon_ember","type":"item","storage":"bag"},"moonstone":{"name":"Лунный камень (редкий)","icon":"icon_shard","type":"item","storage":"bag"},"rare_core":{"name":"Редкое ядро","icon":"icon_core","type":"story","storage":"story"},"forest_mushroom":{"name":"Лесные грибы","icon":"icon_mushroom","type":"item","storage":"bag"},"tree_resin":{"name":"Древесная смола","icon":"icon_resin","type":"item","storage":"bag"},"rune_dust":{"name":"Руническая пыль","icon":"icon_dust","type":"item","storage":"bag"},"frost_herb":{"name":"Морозник","icon":"icon_frost_herb","type":"item","storage":"bag"},"ice_crystal":{"name":"Ледяной кристалл","icon":"icon_ice_crystal","type":"item","storage":"bag"},"frost_shard":{"name":"Инеевый осколок","icon":"icon_frost_shard","type":"item","storage":"bag"},"cold_heart":{"name":"Сердце холода","icon":"icon_cold_heart","type":"item","storage":"bag"},"elixir_life":{"name":"Настой жизни","icon":"icon_potion_life","type":"item","storage":"bag"},"elixir_mana":{"name":"Лунный эликсир","icon":"icon_potion_mana","type":"item","storage":"bag"},"resin_flask":{"name":"Смоляная склянка","icon":"icon_potion_fire","type":"item","storage":"bag"},"warm_potion":{"name":"Тёплый настой","icon":"icon_potion_warm","type":"item","storage":"bag"},"stabilizing_potion":{"name":"Стабилизирующий настой","icon":"icon_potion_stable","type":"item","storage":"bag"},"brittle_flask":{"name":"Флакон Хрупкости","icon":"icon_potion_brittle","type":"item","storage":"bag"},"crystal_guard":{"name":"Кристальная защита","icon":"icon_potion_guard","type":"item","storage":"bag"},"reinforced_resin":{"name":"Усиленная смола","icon":"icon_reinforced_resin","type":"item","storage":"bag"},"astral_lens":{"name":"Астральная линза","icon":"icon_astral_lens","type":"item","storage":"bag"},"amulet_focus":{"name":"Амулет Сосредоточения","icon":"icon_amulet_focus","type":"amulet","storage":"collection"},"amulet_forest":{"name":"Лесной амулет","icon":"icon_amulet_forest","type":"amulet","storage":"collection"},"amulet_lunar":{"name":"Лунный амулет","icon":"icon_amulet_lunar","type":"amulet","storage":"collection"},"amulet_frost":{"name":"Амулет инея","icon":"icon_amulet_frost","type":"amulet","storage":"collection"},"lunar_wick":{"name":"Лунный фитиль","icon":"icon_wick","type":"story","storage":"story"},"revealing_compound":{"name":"Состав ясного взгляда","icon":"icon_compound","type":"story","storage":"story"},"restoration_bundle":{"name":"Целебный сбор","icon":"icon_bundle","type":"story","storage":"story"},"sapphires":{"name":"Сапфиры","icon":"icon_sapphire","type":"sapphire","storage":"wallet"}},"checkpoints":{"forest":{"name":"Лес Мирры","x":1200,"y":4416},"city":{"name":"Вход в город","x":6160,"y":3110,"requires":"ch2_start"},"nerys":{"name":"У Нэрис","x":8300,"y":1960,"requires":"ch2_nerys_met","blockedBy":"ch2_final_start"},"nerys_final":{"name":"У Нэрис перед экзаменом","x":7570,"y":4160,"requires":"ch2_final_start"}},"gifts":{"telekinesis":{"1":"unlock_telekinesis_1","2":"telekinesis_2_complete"},"fire":{"1":"unlock_fire_1"},"seal":{"1":"unlock_seal_1"},"ice":{"1":"unlock_ice_1","2":"unlock_ice_2","3":"ch2_ice3"}},"kits":{"supplies":{"name":"Припасы для теста","items":{"moon_herb":10,"forest_mushroom":5,"tree_resin":5,"rune_dust":5,"elixir_life":3,"elixir_mana":3}}}}$rules$::jsonb) on conflict(key) do update set value=excluded.value;
-- ADMIN_RULES END

create table if not exists game_admin.operations (
  id uuid primary key default gen_random_uuid(), number bigint generated always as identity unique,
  actor uuid, actor_id text, actor_name text, actor_role text, source text not null,
  action text not null, reason text, ref text unique, created_at timestamptz not null default clock_timestamp(),
  detail jsonb not null default '{}', before_state jsonb, after_state jsonb,
  target uuid, reverses uuid unique references game_admin.operations(id)
);
create table if not exists game_admin.entries (
  id bigint generated always as identity primary key, operation uuid not null references game_admin.operations(id),
  user_id uuid not null, player_id text, nickname text, resource text not null, storage text not null,
  delta bigint not null, before_amount bigint not null check(before_amount>=0), after_amount bigint not null check(after_amount>=0),
  created_at timestamptz not null default clock_timestamp()
);
create index if not exists admin_entries_time on game_admin.entries(created_at desc,id desc);
create index if not exists admin_entries_player_time on game_admin.entries(user_id,created_at desc,id desc);
create index if not exists admin_entries_resource_time on game_admin.entries(resource,created_at desc,id desc);
create index if not exists admin_entries_operation on game_admin.entries(operation,id);
create index if not exists admin_operations_time on game_admin.operations(created_at desc,number desc);
create index if not exists admin_operations_target on game_admin.operations(target,created_at desc);
create table if not exists game_admin.requests (
  actor uuid not null, id uuid not null, op text not null, args jsonb not null,
  operation uuid not null references game_admin.operations(id), created_at timestamptz not null default clock_timestamp(),
  primary key(actor,id)
);
create table if not exists game_admin.diagnostics (
  id bigint generated always as identity primary key, user_id uuid, action text not null, code text not null,
  detail jsonb not null default '{}', created_at timestamptz not null default clock_timestamp()
);
create index if not exists admin_diagnostics_time on game_admin.diagnostics(created_at desc,id desc);
create index if not exists admin_diagnostics_player on game_admin.diagnostics(user_id,created_at desc,id desc);

create table if not exists game_admin.combats (
  id bigint generated always as identity primary key,user_id uuid not null,enemy text not null,spawn text,
  outcome text not null check(outcome in ('victory','defeat','retreat')),level int,created_at timestamptz not null default clock_timestamp()
);
create index if not exists admin_combats_time on game_admin.combats(created_at desc);

create or replace function game_admin.reason(s text) returns text language plpgsql immutable set search_path='' as $$
declare t text := btrim(normalize(coalesce(s,''),NFC));
begin
  if char_length(t)>300 or t ~ '[\x00-\x08\x0B\x0C\x0E-\x1F]' then raise exception 'admin_invalid_reason' using errcode='22023'; end if;
  return nullif(t,'');
end $$;
create or replace function game_admin.can_manage(a uuid,t uuid) returns boolean language sql stable set search_path='' as $$
  select game_chat.rank(a)>=3 and ((a=t and game_chat.is_owner(a)) or game_chat.can_manage(a,t))
$$;
create or replace function game_admin.source(op text) returns text language sql immutable set search_path='' as $$
  select case when op like 'shop_%' then 'trade' when op like 'bag_%' then 'bag' when op like 'combat_%' or op='duel_start' then 'combat'
    when op like 'coven_%' then 'coven' when op in ('quest_accept','quest_turn_in','event','daily_take','daily_done','use') then 'quest'
    when op in ('craft','amulet_upgrade') then 'craft' when op in ('research_start','research_finish','research_speedup','respec','build_set','build_preset','preset_unlock') then 'gift'
    when op='bank_welcome' then 'bank' when op='starter_kit' then 'starter' when op='world' then 'world' else 'server' end
$$;
create or replace function game_admin.context(source text,action text,ref text default null,reason text default null,target uuid default null) returns text
language plpgsql set search_path='' as $$
declare prev text := current_setting('game_admin.context',true);
begin
  perform set_config('game_admin.context',jsonb_build_object('id',gen_random_uuid(),'xid',txid_current()::text,'source',source,'action',action,'ref',ref,'reason',reason,'actor',auth.uid(),'target',target)::text,true);
  return coalesce(prev,'');
end $$;
create or replace function game_admin.operation() returns uuid language plpgsql security definer set search_path='' as $$
declare c jsonb; opid uuid; a uuid;
begin
  c:=nullif(current_setting('game_admin.context',true),'')::jsonb;
  if c is null or c->>'xid'<>txid_current()::text then
    perform game_admin.context('server','database_update');
    c:=current_setting('game_admin.context',true)::jsonb;
  end if;
  opid:=(c->>'id')::uuid; a:=(c->>'actor')::uuid;
  insert into game_admin.operations(id,actor,actor_id,actor_name,actor_role,source,action,reason,ref,target)
    values(opid,a,(select player_id::text from public.profiles where id=a),(select coalesce(nickname,'Гость') from public.profiles where id=a),
      (game_chat.user_roles(a))[1],c->>'source',c->>'action',c->>'reason',c->>'ref',(c->>'target')::uuid) on conflict(id) do nothing;
  return opid;
end $$;
create or replace function game_admin.entry(u uuid,k text,storage text,before_amount bigint,after_amount bigint,force_entry boolean default false) returns void
language plpgsql security definer set search_path='' as $$
begin
  if before_amount=after_amount and not force_entry then return; end if;
  insert into game_admin.entries(operation,user_id,player_id,nickname,resource,storage,delta,before_amount,after_amount)
    select game_admin.operation(),u,p.player_id::text,coalesce(p.nickname,'Гость'),k,storage,after_amount-before_amount,before_amount,after_amount from public.profiles p where p.id=u;
end $$;
create or replace function game_admin.log_inventory() returns trigger language plpgsql security definer set search_path='' as $$
declare u uuid; k text; b bigint:=0; a bigint:=0; store text;
begin
  if tg_op<>'INSERT' then u:=old.user_id;k:=old.item_id;b:=old.quantity; end if;
  if tg_op<>'DELETE' then u:=new.user_id;k:=new.item_id;a:=new.quantity; end if;
  if tg_op='UPDATE' and (old.user_id,old.item_id) is distinct from (new.user_id,new.item_id) then
    perform game_admin.entry(old.user_id,old.item_id,coalesce((select value->'catalog'->old.item_id->>'storage' from game_admin.settings where key='rules'),'bag'),old.quantity,0);b:=0;
  end if;
  store:=coalesce((select value->'catalog'->k->>'storage' from game_admin.settings where key='rules'),'bag');
  perform game_admin.entry(u,k,store,b,a);return null;
end $$;
create or replace function game_admin.wallet_revision() returns trigger language plpgsql set search_path='' as $$
begin
  if new.sapphires is distinct from old.sapphires then new.admin_revision:=old.admin_revision+1; end if;return new;
end $$;
create or replace function game_admin.log_wallet() returns trigger language plpgsql security definer set search_path='' as $$
begin
  if tg_op='DELETE' then perform game_admin.entry(old.user_id,'sapphires','wallet',old.sapphires,0);else perform game_admin.entry(new.user_id,'sapphires','wallet',case when tg_op='INSERT' then 0 else old.sapphires end,new.sapphires);end if;return null;
end $$;
create or replace function game_admin.log_bag() returns trigger language plpgsql security definer set search_path='' as $$
declare u uuid; b jsonb:='{}'; a jsonb:='{}'; k text; capb bigint:=100; capa bigint:=100;
begin
  if tg_op<>'INSERT' then if old.kind<>'object' or old.key<>'player_bag' then return null;end if;u:=old.user_id;b:=coalesce(old.data->'pending','{}');capb:=coalesce((old.data->>'capacity')::bigint,100);end if;
  if tg_op<>'DELETE' then if new.kind<>'object' or new.key<>'player_bag' then return null;end if;u:=new.user_id;a:=coalesce(new.data->'pending','{}');capa:=coalesce((new.data->>'capacity')::bigint,100);end if;
  for k in select jsonb_object_keys(b||a) loop perform game_admin.entry(u,k,'pending',coalesce((b->>k)::bigint,0),coalesce((a->>k)::bigint,0));end loop;
  perform game_admin.entry(u,'bag_capacity','capacity',capb,capa);return null;
end $$;
create or replace function game_admin.log_gift() returns trigger language plpgsql security definer set search_path='' as $$
declare u uuid;k text;b bigint:=0;a bigint:=0;
begin
  if tg_op<>'INSERT' then u:=old.user_id;k:=old.ability_id;b:=case when old.unlocked then old.level else 0 end;end if;
  if tg_op<>'DELETE' then u:=new.user_id;k:=new.ability_id;a:=case when new.unlocked then new.level else 0 end;end if;
  perform game_admin.entry(u,'gift:'||k,'gift',b,a);return null;
end $$;
drop trigger if exists admin_inventory_history on public.player_inventory;
create trigger admin_inventory_history after insert or update or delete on public.player_inventory for each row execute function game_admin.log_inventory();
drop trigger if exists admin_wallet_revision on public.player_wallet;
create trigger admin_wallet_revision before update on public.player_wallet for each row execute function game_admin.wallet_revision();
drop trigger if exists admin_wallet_history on public.player_wallet;
create trigger admin_wallet_history after insert or update or delete on public.player_wallet for each row execute function game_admin.log_wallet();
drop trigger if exists admin_bag_history on public.player_world;
create trigger admin_bag_history after insert or update or delete on public.player_world for each row execute function game_admin.log_bag();
drop trigger if exists admin_gift_history on public.player_abilities;
create trigger admin_gift_history after insert or update or delete on public.player_abilities for each row execute function game_admin.log_gift();

-- Copy current gameplay implementations into a private schema. Re-running after
-- schema.sql refreshes a changed core; re-running this migration keeps the core.
do $copy$
declare sig text; fname text; def text;
begin
  foreach sig in array array['player_action(jsonb)','combat_apply(uuid,jsonb)','create_player(text)','reset_player(text)','sync_player(jsonb)','_snapshot(uuid)','admin_grant_sapphires(uuid,bigint,text,text,text)','chat_request(text,jsonb,uuid)','coven_request(text,jsonb)'] loop
    if to_regprocedure('public.'||sig) is null then continue;end if;
    fname:=split_part(sig,'(',1);def:=pg_get_functiondef(to_regprocedure('public.'||sig));
    if position('game_admin.core_'||fname in def)=0 then
      def:=replace(def,'FUNCTION public.'||fname||'(','FUNCTION game_admin.core_'||fname||'(');execute def;
    end if;
  end loop;
end $copy$;

create or replace function public._snapshot(uid uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare s jsonb;
begin
  s:=game_admin.core__snapshot(uid);if s is null then return null;end if;
  return jsonb_set(s,'{meta}',s->'meta'||jsonb_build_object('supportRevision',(select support_revision::text from public.player_progress where user_id=uid)));
end $$;
create or replace function public.player_action(action jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare prev text;outp jsonb;source text;ctx jsonb;
begin
  perform public._require_game_access();
  source:=game_admin.source(action->>'op');
  if action->>'op'='world' and public._game_rules()->'world'->(action->>'obj')->>'kind'='gather' then source:='gather';end if;
  prev:=game_admin.context(source,coalesce(action->>'op','unknown'),null,null,auth.uid());
  if action->>'op'='combat_end' then select combat_ctx into ctx from public.player_progress where user_id=auth.uid() for update;end if;
  outp:=game_admin.core_player_action(action);
  if action->>'op'='combat_end' and outp->'action'->'ok'='true'::jsonb and ctx is not null then
    insert into game_admin.combats(user_id,enemy,spawn,outcome,level) values(auth.uid(),ctx->>'enemy',ctx->>'spawn','retreat',(ctx->>'level')::int);
  end if;
  if outp->'action'->'ok'='false'::jsonb then
    insert into game_admin.diagnostics(user_id,action,code,detail) values(auth.uid(),coalesce(action->>'op','unknown'),coalesce(outp->'action'->>'reason','rejected'),jsonb_strip_nulls(jsonb_build_object('object',action->>'obj','item',action->>'item')));
  end if;
  perform set_config('game_admin.context',prev,true);return outp;
end $$;
create or replace function public.combat_apply(uid uuid,verdict jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare prev text;outp jsonb;ctx jsonb;
begin
  select combat_ctx into ctx from public.player_progress where user_id=uid for update;
  prev:=game_admin.context('combat','combat_apply',null,null,uid);outp:=game_admin.core_combat_apply(uid,verdict);
  if outp->'action'->'ok'='true'::jsonb and ctx is not null then insert into game_admin.combats(user_id,enemy,spawn,outcome,level) values(uid,ctx->>'enemy',ctx->>'spawn',verdict->>'outcome',(ctx->>'level')::int);end if;
  perform set_config('game_admin.context',prev,true);return outp;
end $$;
create or replace function public.create_player(hero text) returns jsonb language plpgsql security definer set search_path='' as $$
declare prev text;outp jsonb;
begin prev:=game_admin.context('starter','create_player',null,null,auth.uid());outp:=game_admin.core_create_player(hero);perform set_config('game_admin.context',prev,true);return outp;end $$;
create or replace function public.reset_player(hero text) returns jsonb language plpgsql security definer set search_path='' as $$
declare prev text;outp jsonb;
begin prev:=game_admin.context('reset','reset_player',null,null,auth.uid());perform game_admin.operation();outp:=game_admin.core_reset_player(hero);perform set_config('game_admin.context',prev,true);return outp;end $$;
create or replace function public.sync_player(patch jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare prev text;outp jsonb;revision text;
begin
  perform public._require_game_access();
  select support_revision::text into revision from public.player_progress where user_id=auth.uid() for update;
  if coalesce(patch->>'supportRevision','0') is distinct from revision then patch:=patch-'pos'-'safe'-'objects';end if;
  prev:=game_admin.context('sync','sync_player',null,null,auth.uid());outp:=game_admin.core_sync_player(patch);perform set_config('game_admin.context',prev,true);return outp;
end $$;
create or replace function public.admin_grant_sapphires(uid uuid,amount bigint,reason text,ref text,kind text default 'admin') returns bigint language plpgsql security definer set search_path='' as $$
declare prev text;outp bigint;
begin prev:=game_admin.context(kind,'grant_sapphires',null,reason,uid);outp:=game_admin.core_admin_grant_sapphires(uid,amount,reason,ref,kind);perform set_config('game_admin.context',prev,true);return outp;end $$;
create or replace function public.chat_request(op text,args jsonb default '{}',request_id uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare prev text;outp jsonb;
begin
  if op='resources' then return game_admin.legacy_resource(args,request_id);end if;
  prev:=game_admin.context('admin','chat:'||op);outp:=game_admin.core_chat_request(op,args,request_id);perform set_config('game_admin.context',prev,true);return outp;
end $$;
create or replace function public.coven_request(op text,args jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare prev text;outp jsonb;
begin prev:=game_admin.context('coven','coven:'||op,null,null,auth.uid());outp:=game_admin.core_coven_request(op,args);perform set_config('game_admin.context',prev,true);return outp;end $$;

-- Read / mutate functions are defined below. All private tables and helpers are
-- revoked together before commit; only admin_request is a browser entry point.

-- The existing client telemetry hook can be used even if the old optional
-- telemetry migration was not installed separately.
create table if not exists public.telemetry_events (
  id bigint generated always as identity primary key, user_id uuid not null,
  session_id text not null check(session_id ~ '^[0-9a-f]{8,32}$'), t_ms bigint not null check(t_ms>=0),
  name text not null check(name ~ '^[a-z0-9_:.]{1,40}$'), data jsonb not null default '{}',
  created_at timestamptz not null default now()
);
create index if not exists telemetry_events_user_idx on public.telemetry_events(user_id,created_at);
create index if not exists telemetry_events_name_idx on public.telemetry_events(name,created_at);
alter table public.telemetry_events enable row level security;
revoke all on public.telemetry_events from public,anon,authenticated;
create or replace function public.telemetry_log(session text,events jsonb) returns int language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();n int;
begin
  if uid is null then raise exception 'not_authenticated' using errcode='28000';end if;
  if session is null or session !~ '^[0-9a-f]{8,32}$' or jsonb_typeof(events) is distinct from 'array' or jsonb_array_length(events)>100 then return 0;end if;
  if (select count(*) from public.telemetry_events where user_id=uid and created_at>now()-interval '1 day')>=6000 then return 0;end if;
  insert into public.telemetry_events(user_id,session_id,t_ms,name,data)
    select uid,session,least(greatest((e->>'t')::bigint,0),604800000),e->>'n',case when jsonb_typeof(e->'d')='object' and length((e->'d')::text)<=600 then e->'d' else '{}'::jsonb end
      from jsonb_array_elements(events) e where jsonb_typeof(e)='object' and (e->>'n') ~ '^[a-z0-9_:.]{1,40}$' and (e->>'t') ~ '^[0-9]{1,12}$';
  get diagnostics n=row_count;return n;
end $$;

create or replace function game_admin.person(u uuid) returns jsonb language sql stable set search_path='' as $$
  select jsonb_build_object('playerId',p.player_id::text,'nickname',coalesce(p.nickname,'Гость'),'role',coalesce((game_chat.user_roles(u))[1],'player')) from public.profiles p where p.id=u
$$;
create or replace function game_admin.summary(u uuid) returns jsonb language sql stable set search_path='' as $$
  select game_admin.person(u)||jsonb_build_object('registered',p.nickname is not null,'hero',p.hero_id,'level',g.hero_level,
    'registeredAt',p.registered_at,'createdAt',p.created_at,'lastSeenAt',p.last_seen_at,
    'online',coalesce((to_jsonb(p)->>'online_at')::timestamptz,p.last_seen_at)>now()-interval '120 seconds',
    'chapter',case when exists(select 1 from public.player_quests where user_id=u and quest_id='chapter_2_complete' and status='done') then 3
      when exists(select 1 from public.player_quests where user_id=u and quest_id='ch2_start' and status='done') then 2 else 1 end,
    'lastStepAt',(select max(updated_at) from public.player_quests where user_id=u and status='done'))
  from public.profiles p join public.player_progress g on g.user_id=p.id where p.id=u
$$;
create or replace function game_admin.gift_levels(u uuid) returns jsonb language plpgsql stable set search_path='' as $$
declare cfg jsonb;ab text;lvl text;ev jsonb;mx bigint;r jsonb:='{}';
begin
  select value->'gifts' into cfg from game_admin.settings where key='rules';
  for ab in select jsonb_object_keys(cfg) loop
    select coalesce(max(after_amount),0) into mx from game_admin.entries ge where user_id=u and resource='gift:'||ab and not exists(select 1 from game_admin.operations ro where ro.reverses=ge.operation) and created_at>coalesce((select max(created_at) from game_admin.operations where target=u and source='reset'),'-infinity'::timestamptz);
    for lvl,ev in select * from jsonb_each(cfg->ab) loop
      if public._has_event(u,ev#>>'{}') then mx:=greatest(mx,lvl::bigint);end if;
    end loop;
    r:=r||jsonb_build_object(ab,least(3,mx));
  end loop;return r;
end $$;
create or replace function game_admin.player(u uuid,viewer uuid) returns jsonb language plpgsql stable set search_path='' as $$
declare s jsonb;cfg jsonb;hp numeric;mp numeric;coven jsonb;device jsonb;
begin
  s:=public._snapshot(u);if s is null then raise exception 'admin_not_found';end if;
  select value into cfg from game_admin.settings where key='rules';
  select max_hp,max_mana into hp,mp from public.game_hero_levels where level=(s->>'level')::int;
  if to_regclass('public.coven_members') is not null then
    execute 'select jsonb_build_object(''name'',c.name,''role'',m.role,''contribution'',m.week_given) from public.coven_members m join public.covens c on c.id=m.coven_id where m.user_id=$1' into coven using u;
  end if;
  select data||jsonb_build_object('at',created_at) into device from public.telemetry_events where user_id=u and name='session_start' order by created_at desc limit 1;
  return game_admin.summary(u)||jsonb_build_object('snapshot',s,'revision',s->'meta'->>'rev',
    'walletRevision',coalesce((select admin_revision::text from public.player_wallet where user_id=u),'0'),
    'maxHp',hp,'maxMana',mp,'bagUsed',public._bag_used(u),'coven',coven,'device',device,
    'canManage',game_admin.can_manage(viewer,u),'canSapphires',game_chat.is_admin(viewer) and game_admin.can_manage(viewer,u),
    'earnedGifts',game_admin.gift_levels(u),
    'checkpoints',(select coalesce(jsonb_object_agg(k,v),'{}') from jsonb_each(cfg->'checkpoints') x(k,v)
      where (v->>'requires' is null or public._has_event(u,v->>'requires')) and (v->>'blockedBy' is null or not public._has_event(u,v->>'blockedBy'))));
end $$;

create or replace function game_admin.operation_dto(o game_admin.operations,full_detail boolean default false) returns jsonb language sql stable set search_path='' as $$
  select jsonb_build_object('id',o.id,'number',o.number::text,'source',o.source,'action',o.action,'reason',o.reason,'ref',o.ref,'createdAt',o.created_at,
    'actor',jsonb_build_object('playerId',o.actor_id,'nickname',coalesce(o.actor_name,'Сервер'),'role',coalesce(o.actor_role,'system')),
    'player',game_admin.person(o.target),'detail',o.detail,'reverses',o.reverses,
    'reversedBy',(select id from game_admin.operations where reverses=o.id),
    'restorable',o.before_state is not null and o.after_state is not null and o.reverses is null and not exists(select 1 from game_admin.operations where reverses=o.id))
    ||case when full_detail then jsonb_build_object('before',o.before_state,'after',o.after_state) else '{}'::jsonb end
$$;

create or replace function game_admin.apply_resources(u uuid,changes jsonb,request_id uuid) returns void language plpgsql set search_path='' as $$
declare c jsonb;k text;delta bigint;store text;have bigint;free bigint;into_bag bigint;b jsonb;cfg jsonb;pending bigint;
begin
  select value into cfg from game_admin.settings where key='rules';
  if jsonb_typeof(changes) is distinct from 'array' or jsonb_array_length(changes) not between 1 and 30 then raise exception 'admin_invalid_request';end if;
  for c in select * from jsonb_array_elements(changes) loop
    if jsonb_typeof(c) is distinct from 'object' or exists(select 1 from jsonb_object_keys(c) zkey where zkey not in ('item','delta','storage')) then raise exception 'admin_invalid_request';end if;
    k:=c->>'item';store:=coalesce(c->>'storage','inventory');
    if not(cfg->'catalog' ? k) or coalesce(c->>'delta','') !~ '^-?[1-9][0-9]{0,6}$' or abs((c->>'delta')::bigint)>1000000 or store not in ('inventory','pending') then raise exception 'admin_invalid_request';end if;
    delta:=(c->>'delta')::bigint;
    if k='sapphires' then
      if not game_chat.is_admin(auth.uid()) then raise exception 'admin_forbidden' using errcode='42501';end if;
      if store<>'inventory' then raise exception 'admin_invalid_request';end if;
      have:=public._sapphires(u);
      if have+delta<0 or have+delta>1000000000 then raise exception 'admin_balance';end if;
      -- One request may contain several sapphire lines; each line gets its own ref.
      perform public._sapphire_add(u,delta,'admin',(current_setting('game_admin.context',true)::jsonb->>'reason'),'admin:'||request_id::text||':'||gen_random_uuid()::text);
    elsif store='pending' then
      if not(public._game_rules()->'bag'->'items' ? k) or delta>0 then raise exception 'admin_invalid_request';end if;
      b:=public._bag(u);have:=coalesce((b->'pending'->>k)::bigint,0);
      if have+delta<0 then raise exception 'admin_balance';end if;
      b:=jsonb_set(b,array['pending',k],to_jsonb(have+delta));if have+delta=0 then b:=b#-array['pending',k];end if;perform public._bag_write(u,b);
    else
      have:=public._inv(u,k);
      if delta<0 then
        if have+delta<0 then raise exception 'admin_balance';end if;perform public._inv_add(u,k,delta);
      elsif public._game_rules()->'bag'->'items' ? k then
        b:=public._bag(u);free:=greatest(0,(b->>'capacity')::bigint-public._bag_used(u));into_bag:=least(free,delta);pending:=coalesce((b->'pending'->>k)::bigint,0);
        if have+into_bag>1000000000 or pending+delta-into_bag>1000000000 then raise exception 'admin_balance';end if;
        if into_bag>0 then perform public._inv_add(u,k,into_bag);end if;
        if delta>into_bag then b:=jsonb_set(b,array['pending',k],to_jsonb(pending+delta-into_bag),true);perform public._bag_write(u,b);end if;
      else
        if have+delta>1000000000 then raise exception 'admin_balance';end if;perform public._inv_add(u,k,delta);
      end if;
    end if;
  end loop;
end $$;

create or replace function game_admin.apply_help(u uuid,args jsonb) returns void language plpgsql set search_path='' as $$
declare pr public.player_progress%rowtype;cmd text:=args->>'command';r jsonb;cfg jsonb;pt jsonb;ab text;lvl int;earned jsonb;mxhp numeric;mxmp numeric;
begin
  select * into pr from public.player_progress where user_id=u for update;pr:=public._advance(pr);
  select value into cfg from game_admin.settings where key='rules';
  if pr.combat_since is not null and cmd<>'stop_combat' then raise exception 'admin_in_combat';end if;
  if cmd='heal' then
    select max_hp,max_mana into mxhp,mxmp from public.game_hero_levels where level=pr.hero_level;pr.hp:=mxhp;pr.mana:=mxmp;
  elsif cmd='stop_combat' then
    pr.combat_since:=null;pr.combat_ctx:=null;
  elsif cmd='teleport' then
    pt:=cfg->'checkpoints'->(args->>'checkpoint');
    if pt is null or (pt->>'requires' is not null and not public._has_event(u,pt->>'requires')) or (pt->>'blockedBy' is not null and public._has_event(u,pt->>'blockedBy')) then raise exception 'admin_checkpoint_locked';end if;
    pr.pos_x:=(pt->>'x')::double precision;pr.pos_y:=(pt->>'y')::double precision;pr.safe_x:=pr.pos_x;pr.safe_y:=pr.pos_y;
  elsif cmd='repair_gift' then
    ab:=args->>'ability';earned:=game_admin.gift_levels(u);lvl:=coalesce((earned->>ab)::int,0);
    if lvl=0 then raise exception 'admin_no_proof';end if;
    if coalesce((select level from public.player_abilities where user_id=u and ability_id=ab and unlocked),0)>=lvl then raise exception 'admin_no_change';end if;
    perform public._unlock_ability(u,ab,lvl);
  elsif cmd='finish_research' then
    r:=public._game_rules()->'research'->(pr.research->>'upgradeId');if r is null then raise exception 'admin_no_research';end if;
    perform public._unlock_ability(u,r->>'ability',(r->>'toLevel')::int);
    if r->>'branch' is not null then perform public._set_branch(u,r->>'ability',r->>'branch');end if;
    pr.research:=null;
    if r->>'completeEvent' is not null then pr:=public._set_event(u,pr,r->>'completeEvent',public._game_rules());end if;
  else raise exception 'admin_invalid_request';end if;
  update public.player_progress set hero_level=pr.hero_level,hero_xp=pr.hero_xp,school_xp=pr.school_xp,research=pr.research,
    pos_x=pr.pos_x,pos_y=pr.pos_y,safe_x=pr.safe_x,safe_y=pr.safe_y,hp=pr.hp,mana=pr.mana,vitals_at=pr.vitals_at,
    combat_since=pr.combat_since,combat_ctx=pr.combat_ctx,support_revision=support_revision+1 where user_id=u;
end $$;

create or replace function game_admin.restore(u uuid,opid uuid) returns void language plpgsql set search_path='' as $$
declare o game_admin.operations%rowtype;e record;b jsonb;wanted jsonb;k text;pr public.player_progress%rowtype;
begin
  select * into o from game_admin.operations where id=opid for update;
  if not game_chat.is_admin(auth.uid()) then raise exception 'admin_forbidden' using errcode='42501';end if;
  if o.target is distinct from u or o.before_state is null or o.after_state is null or o.reverses is not null or exists(select 1 from game_admin.operations where reverses=opid) then raise exception 'admin_not_restorable';end if;
  select * into pr from public.player_progress where user_id=u for update;
  if pr.rev::text is distinct from o.after_state->'meta'->>'rev' or coalesce((select admin_revision::text from public.player_wallet where user_id=u),'0') is distinct from o.detail->>'walletRevision' then raise exception 'admin_restore_conflict';end if;
  if pr.combat_since is not null then raise exception 'admin_in_combat';end if;
  -- Undo only recorded changes; no new request-supplied snapshot can enter here.
  for e in select resource,storage,sum(delta)::bigint delta from game_admin.entries where operation=opid and user_id=u group by resource,storage loop
    if e.storage='wallet' and e.resource='sapphires' then
      perform public._sapphire_add(u,-e.delta,'admin',null,'restore:'||game_admin.operation()::text);
    elsif e.storage='pending' then
      b:=public._bag(u);wanted:=to_jsonb(coalesce((b->'pending'->>e.resource)::bigint,0)-e.delta);
      if (wanted#>>'{}')::bigint<0 then raise exception 'admin_balance';end if;
      b:=jsonb_set(b,array['pending',e.resource],wanted,true);perform public._bag_write(u,b);
    elsif e.storage in ('wallet','bag','collection','story') then
      -- Capacity is checked against the captured state, not current free space.
      insert into public.player_inventory(user_id,item_id,quantity) values(u,e.resource,public._inv(u,e.resource)-e.delta)
        on conflict(user_id,item_id) do update set quantity=excluded.quantity;
    elsif e.storage='gift' then
      k:=split_part(e.resource,':',2);wanted:=o.before_state->'abilities'->k;
      if wanted is null then delete from public.player_abilities where user_id=u and ability_id=k;
      else insert into public.player_abilities(user_id,ability_id,level,unlocked) values(u,k,(wanted->>'level')::int,(wanted->>'unlocked')::boolean) on conflict(user_id,ability_id) do update set level=excluded.level,unlocked=excluded.unlocked;end if;
    end if;
  end loop;
  if o.action like 'help:%' then
    b:=o.before_state;
    update public.player_progress set hero_level=(b->>'level')::int,hero_xp=(b->>'xp')::bigint,school_xp=b->'school',research=nullif(b->'research','null'),
      pos_x=(b->'pos'->>'x')::double precision,pos_y=(b->'pos'->>'y')::double precision,safe_x=(b->'safe'->>'x')::double precision,safe_y=(b->'safe'->>'y')::double precision,
      hp=(b->>'hp')::double precision,mana=(b->>'mana')::double precision,vitals_at=date_trunc('milliseconds',now()),combat_since=null,combat_ctx=null,support_revision=support_revision+1 where user_id=u;
    delete from public.player_quests where user_id=u and not (b->'quests' ? quest_id);
    insert into public.player_quests(user_id,quest_id) select u,jsonb_array_elements_text(b->'quests') on conflict(user_id,quest_id) do update set status='done';
    -- Research completion can change a branch; keep all unrelated world objects.
    wanted:=b->'objects'->'player_build';if wanted is null then delete from public.player_world where user_id=u and kind='object' and key='player_build';
    else insert into public.player_world(user_id,kind,key,data) values(u,'object','player_build',wanted) on conflict(user_id,kind,key) do update set data=excluded.data;end if;
  end if;
  update game_admin.operations set reverses=opid where id=game_admin.operation();
end $$;

create or replace function game_admin.mutate(op text,args jsonb,request_id uuid) returns jsonb language plpgsql set search_path='' as $$
declare a uuid:=auth.uid();u uuid;lk bigint;pr public.player_progress%rowtype;req game_admin.requests%rowtype;
  prev text;oid uuid;why text;b jsonb;s jsonb;wr text;action text;changes jsonb;
begin
  if request_id is null or jsonb_typeof(args)<>'object' or length(args::text)>12000 then raise exception 'admin_invalid_request';end if;
  if coalesce(args->>'playerId','') !~ '^[0-9]{1,19}$' then raise exception 'admin_not_found';end if;
  select id into u from public.profiles where player_id::text=args->>'playerId';if u is null then raise exception 'admin_not_found';end if;
  for lk in select distinct hashtextextended('chat-user:'||x::text,0) from unnest(array[a,u]) x order by 1 loop perform pg_advisory_xact_lock(lk);end loop;
  if not game_admin.can_manage(a,u) then raise exception 'admin_forbidden' using errcode='42501';end if;
  if game_chat.banned(a,'game') then raise exception 'game_banned';end if;
  select * into req from game_admin.requests where actor=a and id=request_id;
  if found then
    if req.op<>op or req.args<>args then raise exception 'admin_request_reused';end if;
    return jsonb_build_object('player',game_admin.player(u,a),'operation',req.operation,'repeated',true);
  end if;
  select * into pr from public.player_progress where user_id=u for update;
  if not found then raise exception 'admin_not_found';end if;
  perform 1 from public.player_wallet where user_id=u for update;
  wr:=coalesce((select admin_revision::text from public.player_wallet where user_id=u),'0');
  if coalesce(args->>'revision','')<>pr.rev::text or coalesce(args->>'walletRevision',wr)<>wr then raise exception 'admin_conflict';end if;
  if exists(select 1 from jsonb_object_keys(args) k where k not in ('playerId','revision','walletRevision','reason','changes','command','ability','checkpoint','operation','kit')) then raise exception 'admin_invalid_request';end if;
  why:=game_admin.reason(args->>'reason');b:=public._snapshot(u);
  action:=case when op='help' then 'help:'||coalesce(args->>'command','') else op end;
  prev:=game_admin.context('admin',action,'admin:'||a::text||':'||request_id::text,why,u);oid:=game_admin.operation();
  if op='resources' then
    changes:=args->'changes';
    if args ? 'kit' then
      changes:=(select jsonb_agg(jsonb_build_object('item',k,'delta',v)) from jsonb_each((select value->'kits'->(args->>'kit')->'items' from game_admin.settings where key='rules')) x(k,v));
    end if;
    perform game_admin.apply_resources(u,changes,request_id);
  elsif op='help' then perform game_admin.apply_help(u,args);
  elsif op='restore' then perform game_admin.restore(u,(args->>'operation')::uuid);
  else raise exception 'admin_invalid_request';end if;
  update public.player_progress set rev=rev+1 where user_id=u;
  update public.profiles set staff_revision=staff_revision+1 where id=u;
  s:=public._snapshot(u);
  update game_admin.operations set before_state=b,after_state=s,
    detail=jsonb_build_object('command',args->>'command','ability',args->>'ability','checkpoint',args->>'checkpoint','kit',args->>'kit',
      'walletRevision',coalesce((select admin_revision::text from public.player_wallet where user_id=u),'0')) where id=oid;
  insert into game_admin.requests(actor,id,op,args,operation) values(a,request_id,op,args,oid);
  perform set_config('game_admin.context',prev,true);
  return jsonb_build_object('player',game_admin.player(u,a),'operation',oid,'repeated',false);
end $$;

create or replace function game_admin.legacy_resource(args jsonb,request_id uuid) returns jsonb language plpgsql set search_path='' as $$
declare r jsonb;u uuid;beforeqty bigint;
begin
  select id into u from public.profiles where player_id::text=args->>'playerId';beforeqty:=public._inv(u,args->>'item');
  if exists(select 1 from jsonb_object_keys(args) k where k not in ('playerId','revision','item','delta','reason')) then raise exception 'chat_invalid_request';end if;
  begin
    r:=game_admin.mutate('resources',jsonb_build_object('playerId',args->>'playerId','revision',args->>'revision','reason',args->>'reason',
      'changes',jsonb_build_array(jsonb_build_object('item',args->>'item','delta',args->'delta'))),request_id);
  exception when others then
    if sqlerrm='admin_conflict' then raise exception 'chat_conflict';
    elsif sqlerrm='admin_forbidden' then raise exception 'chat_forbidden' using errcode='42501';
    elsif sqlerrm like 'admin_%' then raise exception 'chat_invalid_request';else raise;end if;
  end;
  select coalesce((before_state->'inventory'->>(args->>'item'))::bigint,0) into beforeqty from game_admin.operations where id=(r->>'operation')::uuid;
  if not (r->>'repeated')::boolean then perform game_chat.log(auth.uid(),'resources',u,jsonb_build_object('item',args->>'item','delta',args->'delta','before',beforeqty,'after',public._inv(u,args->>'item'),'reason',args->>'reason','operation',r->>'operation'));end if;
  return game_chat.staff_player(u,auth.uid());
end $$;

create or replace function public.admin_request(op text,args jsonb default '{}',request_id uuid default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare a uuid:=auth.uid();u uuid;r jsonb;rows jsonb;cfg jsonb;lim int;offp int;dt timestamptz;dt2 timestamptz;curtime timestamptz;curid bigint;oprow game_admin.operations%rowtype;
begin
  if a is null then raise exception 'not_authenticated' using errcode='28000';end if;
  if game_chat.rank(a)<2 then raise exception 'admin_forbidden' using errcode='42501';end if;
  if jsonb_typeof(args) is distinct from 'object' or length(args::text)>12000 then raise exception 'admin_invalid_request';end if;
  if op in ('resources','help','restore') then return game_admin.mutate(op,args,request_id);end if;
  select value into cfg from game_admin.settings where key='rules';
  lim:=least(100,greatest(1,coalesce((args->>'limit')::int,50)));offp:=least(100000,greatest(0,coalesce((args->>'offset')::int,0)));
  dt:=nullif(args->>'from','')::timestamptz;dt2:=nullif(args->>'to','')::timestamptz;
  curtime:=(args->'cursor'->>'at')::timestamptz;curid:=(args->'cursor'->>'id')::bigint;
  if args ? 'playerId' then
    select id into u from public.profiles where player_id::text=args->>'playerId';if u is null then raise exception 'admin_not_found';end if;
  end if;
  if op='bootstrap' then
    return jsonb_build_object('me',game_admin.person(a),'catalog',cfg->'catalog','kits',cfg->'kits','installedAt',(select value from game_admin.settings where key='installedAt'),'timezone','Asia/Yekaterinburg');
  elsif op='player' then return game_admin.player(u,a);
  elsif op='players' then
    select coalesce(jsonb_agg(j order by pid),'[]') into rows from (
      select p.player_id pid,game_admin.summary(p.id) j from public.profiles p join public.player_progress g on g.user_id=p.id
      where (coalesce(args->>'q','')='' or p.player_id::text=args->>'q' or p.nickname ilike '%'||(args->>'q')||'%')
      and (coalesce(args->>'chapter','')='' or (game_admin.summary(p.id)->>'chapter')=args->>'chapter')
      and (coalesce(args->>'online','')<>'true' or p.online_at>now()-interval '120 seconds')
      order by p.player_id limit lim+1 offset offp
    ) x;
    return jsonb_build_object('rows',case when jsonb_array_length(rows)>lim then rows-lim else rows end,'hasMore',jsonb_array_length(rows)>lim);
  elsif op='ledger' then
    select coalesce(jsonb_agg(j order by created_at desc,id desc),'[]') into rows from (
      select e.id,e.created_at,jsonb_build_object('id',e.id::text,'operation',o.id,'number',o.number::text,'at',e.created_at,
        'player',jsonb_build_object('playerId',e.player_id,'nickname',e.nickname),'resource',e.resource,'storage',e.storage,'delta',e.delta,'before',e.before_amount,'after',e.after_amount,
        'source',o.source,'action',o.action,'reason',o.reason,'actor',jsonb_build_object('playerId',o.actor_id,'nickname',o.actor_name,'role',o.actor_role)) j
      from game_admin.entries e join game_admin.operations o on o.id=e.operation
      where (u is null or e.user_id=u) and (dt is null or e.created_at>=dt) and (dt2 is null or e.created_at<=dt2)
      and (curtime is null or (e.created_at,e.id)<(curtime,curid))
      and (coalesce(args->>'source','')='' or o.source=args->>'source')
      and (coalesce(args->>'resource','')='' or e.resource=args->>'resource')
      and (coalesce(args->>'type','')='' or cfg->'catalog'->e.resource->>'type'=args->>'type' or args->>'type'=e.storage)
      and (coalesce(args->>'storage','')='' or e.storage=args->>'storage')
      and (coalesce(args->>'direction','')='' or (args->>'direction'='in' and e.delta>0) or (args->>'direction'='out' and e.delta<0))
      and (coalesce(args->>'q','')='' or e.player_id=args->>'q' or o.number::text=ltrim(args->>'q','#') or o.actor_id=ltrim(args->>'q','#') or e.nickname ilike '%'||(args->>'q')||'%' or coalesce(o.actor_name,'') ilike '%'||(args->>'q')||'%' or coalesce(o.reason,'') ilike '%'||(args->>'q')||'%' or cfg->'catalog'->e.resource->>'name' ilike '%'||(args->>'q')||'%')
      order by e.created_at desc,e.id desc limit lim+1
    ) x;
    if jsonb_array_length(rows)>lim then rows:=rows-lim;r:=jsonb_build_object('hasMore',true,'next',jsonb_build_object('at',rows->(lim-1)->>'at','id',rows->(lim-1)->>'id'));else r:=jsonb_build_object('hasMore',false);end if;
    return r||jsonb_build_object('rows',rows,'installedAt',(select value from game_admin.settings where key='installedAt'));
  elsif op='operation' then
    select * into oprow from game_admin.operations where id=(args->>'operation')::uuid;if not found then raise exception 'admin_not_found';end if;
    select coalesce(jsonb_agg(jsonb_build_object('player',jsonb_build_object('playerId',player_id,'nickname',nickname),'resource',resource,'storage',storage,'delta',delta,'before',before_amount,'after',after_amount) order by id),'[]') into rows from game_admin.entries where operation=oprow.id;
    return game_admin.operation_dto(oprow,game_chat.is_admin(a))||jsonb_build_object('entries',rows,'canRestore',game_chat.is_admin(a) and game_admin.can_manage(a,oprow.target));
  elsif op='audit' then
    select coalesce(jsonb_agg(j order by at desc),'[]') into rows from (
      select created_at at,game_admin.operation_dto(x) j from game_admin.operations x where source='admin' and (u is null or target=u) and (dt is null or created_at>=dt) and (dt2 is null or created_at<=dt2)
        and (coalesce(args->>'q','')='' or actor_name ilike '%'||(args->>'q')||'%' or coalesce(reason,'') ilike '%'||(args->>'q')||'%')
      union all select created_at,jsonb_build_object('id','chat:'||id,'at',created_at,'source','chat','action',action,'reason',detail->>'reason','actor',game_admin.person(actor),'player',game_admin.person(target),'detail',detail)
      from game_chat.audit where not(detail ? 'operation') and (u is null or target=u) and (dt is null or created_at>=dt) and (dt2 is null or created_at<=dt2)
        and (coalesce(args->>'q','')='' or detail->>'reason' ilike '%'||(args->>'q')||'%' or game_admin.person(actor)->>'nickname' ilike '%'||(args->>'q')||'%')
      order by at desc limit lim+1 offset offp
    ) x;
    return jsonb_build_object('rows',case when jsonb_array_length(rows)>lim then rows-lim else rows end,'hasMore',jsonb_array_length(rows)>lim);
  elsif op='errors' then
    select coalesce(jsonb_agg(j order by at desc),'[]') into rows from (
      select d.created_at at,jsonb_build_object('id','server:'||d.id,'at',d.created_at,'player',game_admin.person(d.user_id),'origin','server','code',d.code,'action',d.action,'detail',d.detail) j
        from game_admin.diagnostics d where (u is null or d.user_id=u) and (dt is null or d.created_at>=dt) and (dt2 is null or d.created_at<=dt2)
          and (coalesce(args->>'q','')='' or d.code ilike '%'||(args->>'q')||'%' or d.action ilike '%'||(args->>'q')||'%')
      union all select t.created_at,jsonb_build_object('id','client:'||t.id,'at',t.created_at,'player',game_admin.person(t.user_id),'origin','client','code',coalesce(t.data->>'code',t.data->>'msg',t.data->>'message',t.name),'action',t.name,'detail',t.data,'device',(select z.data from public.telemetry_events z where z.user_id=t.user_id and z.session_id=t.session_id and z.name='session_start' order by z.created_at limit 1))
        from public.telemetry_events t where t.name in ('js_error','promise_error','sync_reject','action_error','session_error','fatal_error') and (u is null or t.user_id=u)
          and (dt is null or t.created_at>=dt) and (dt2 is null or t.created_at<=dt2) and (coalesce(args->>'q','')='' or t.data::text ilike '%'||(args->>'q')||'%')
      order by at desc limit lim+1 offset offp
    ) x;
    return jsonb_build_object('rows',case when jsonb_array_length(rows)>lim then rows-lim else rows end,'hasMore',jsonb_array_length(rows)>lim);
  elsif op='stats' then
    select jsonb_build_object('players',count(*),'registered',count(*) filter(where p.nickname is not null),'online',count(*) filter(where p.online_at>now()-interval '120 seconds'),
      'chapter1',count(*) filter(where not public._has_event(p.id,'ch2_start')),'chapter2',count(*) filter(where public._has_event(p.id,'ch2_start') and not public._has_event(p.id,'chapter_2_complete')),
      'completed',count(*) filter(where public._has_event(p.id,'chapter_2_complete')),'coins',coalesce(sum(public._inv(p.id,'coins')),0),'sapphires',coalesce(sum(w.sapphires),0)) into r
      from public.profiles p join public.player_progress g on g.user_id=p.id left join public.player_wallet w on w.user_id=p.id where (dt is null or p.created_at>=dt) and (dt2 is null or p.created_at<=dt2);
    select coalesce(jsonb_agg(to_jsonb(x)),'[]') into rows from (
      select e.resource,o.source,sum(e.delta) filter(where e.delta>0) incoming,-sum(e.delta) filter(where e.delta<0) outgoing,count(*) changes
      from game_admin.entries e join game_admin.operations o on o.id=e.operation where e.resource in ('coins','sapphires') and o.source<>'opening'
        and (dt is null or e.created_at>=dt) and (dt2 is null or e.created_at<=dt2) group by e.resource,o.source order by e.resource,o.source
    ) x;
    return r||jsonb_build_object('flows',rows,'combats',(select coalesce(jsonb_agg(to_jsonb(z)),'[]') from (select enemy,count(*) fights,count(*) filter(where outcome='victory') wins,count(*) filter(where outcome='defeat') defeats,count(*) filter(where outcome='retreat') retreats from game_admin.combats where (dt is null or created_at>=dt) and (dt2 is null or created_at<=dt2) group by enemy order by count(*) desc) z),'installedAt',(select value from game_admin.settings where key='installedAt'));
  else raise exception 'admin_invalid_request';end if;
end $$;

-- Known historical movements are imported once. Earlier item movements that were
-- never logged cannot be reconstructed: zero-delta rows identify starting balances.
do $history$
declare x record;oid uuid;prev text;cat jsonb;
begin
  select value->'catalog' into cat from game_admin.settings where key='rules';
  for x in select l.* from public.sapphire_ledger l where l.created_at<=(select (value#>>'{}')::timestamptz from game_admin.settings where key='installedAt') and not exists(select 1 from game_admin.operations where ref='legacy-sapphire:'||l.id) loop
    oid:=gen_random_uuid();
    insert into game_admin.operations(id,source,action,ref,reason,target,created_at) values(oid,x.kind,'legacy_sapphire','legacy-sapphire:'||x.id,x.reason,x.user_id,x.created_at);
    insert into game_admin.entries(operation,user_id,player_id,nickname,resource,storage,delta,before_amount,after_amount,created_at)
      select oid,x.user_id,p.player_id::text,p.nickname,'sapphires','wallet',x.delta,x.balance-x.delta,x.balance,x.created_at from public.profiles p where p.id=x.user_id;
  end loop;
  for x in select h.* from game_chat.audit h where h.action='resources' and h.created_at<=(select (value#>>'{}')::timestamptz from game_admin.settings where key='installedAt') and not exists(select 1 from game_admin.operations where ref='legacy-chat:'||h.id) loop
    if coalesce(x.detail->>'before','') !~ '^[0-9]+$' or coalesce(x.detail->>'after','') !~ '^[0-9]+$' then continue;end if;
    oid:=gen_random_uuid();insert into game_admin.operations(id,actor,actor_id,actor_name,actor_role,source,action,ref,reason,target,created_at)
      select oid,x.actor,p.player_id::text,p.nickname,(game_chat.user_roles(x.actor))[1],'admin','legacy_resources','legacy-chat:'||x.id,x.detail->>'reason',x.target,x.created_at from public.profiles p where p.id=x.actor;
    insert into game_admin.entries(operation,user_id,player_id,nickname,resource,storage,delta,before_amount,after_amount,created_at)
      select oid,x.target,p.player_id::text,p.nickname,x.detail->>'item',coalesce(cat->(x.detail->>'item')->>'storage','bag'),(x.detail->>'after')::bigint-(x.detail->>'before')::bigint,(x.detail->>'before')::bigint,(x.detail->>'after')::bigint,x.created_at from public.profiles p where p.id=x.target;
  end loop;
  if not exists(select 1 from game_admin.settings where key='openingRecorded') then
    for x in select id from public.profiles p where exists(select 1 from public.player_progress g where g.user_id=p.id) loop
      prev:=game_admin.context('opening','opening_balances','opening:'||x.id::text,null,x.id);
      perform game_admin.entry(x.id,i.item_id,coalesce(cat->i.item_id->>'storage','bag'),i.quantity,i.quantity,true) from public.player_inventory i where i.user_id=x.id;
      perform game_admin.entry(x.id,'sapphires','wallet',w.sapphires,w.sapphires,true) from public.player_wallet w where w.user_id=x.id;
      perform game_admin.entry(x.id,k,'pending',v::bigint,v::bigint,true) from jsonb_each_text(public._bag(x.id)->'pending') b(k,v);
      perform game_admin.entry(x.id,'gift:'||ability_id,'gift',case when unlocked then level else 0 end,case when unlocked then level else 0 end,true) from public.player_abilities where user_id=x.id;
      perform set_config('game_admin.context',prev,true);
    end loop;
    insert into game_admin.settings values('openingRecorded',to_jsonb(clock_timestamp()));
  end if;
end $history$;

-- Defense in depth: no browser role can read tables or call copied gameplay cores.
do $acl$ declare t record;begin
  for t in select tablename from pg_tables where schemaname='game_admin' loop execute format('alter table game_admin.%I enable row level security',t.tablename);end loop;
end $acl$;
revoke all on all tables in schema game_admin from public,anon,authenticated,service_role;
revoke all on all sequences in schema game_admin from public,anon,authenticated,service_role;
revoke all on all functions in schema game_admin from public,anon,authenticated,service_role;
revoke all on function public.admin_request(text,jsonb,uuid),public.telemetry_log(text,jsonb) from public,anon,authenticated;
grant execute on function public.admin_request(text,jsonb,uuid),public.telemetry_log(text,jsonb) to authenticated;
revoke all on function public.combat_apply(uuid,jsonb),public.admin_grant_sapphires(uuid,bigint,text,text,text),public._snapshot(uuid) from public,anon,authenticated;
grant execute on function public.combat_apply(uuid,jsonb),public.admin_grant_sapphires(uuid,bigint,text,text,text) to service_role;
commit;
